 if 'events' in T[sid]:lines.append(f'Selected same-kind timing artifact: lead-timing.json, P={T[sid]["period_days"]:.8f} d with explicit cycles and residuals. Its formal error is conditional on those selections.'+(' This is not an adopted orbital period.' if n['period']=='' else ''))
 if sid in A:lines.append(f'Bounded integer-cycle coverage/null audit: lead-alias.json; tested {len(A[sid]["trials"])} aliases, with each actual core and side-band cadence audit saved. Deciding shorter-alias windows were also plotted in lead-deciding-null-*.png; the numeric screen alone is not a physical veto.')
 lines += [f'Current Tesscut footprint query returns sectors {AV[sid]["sectors"]}. This is sector availability, not an assertion that all have usable raw QLP files or sensitive eclipse windows.',n['source'],f'Limitation: {n["limits"]}',f'Next check: {n["next"]}','', '## Provenance','',f'Source packet: {B.parent / "source-packets" / tic / "sources.json"}',f'Shared catalogue evidence: {S / "target-evidence.json"} (row {sid}); shared 120-arcsec Gaia neighbor query and source receipts are in shared-catalogues.',f'Independent TESScut receipt: {B / tic / ("helper-s"+str(pix["sector"])+"-receipt.json")}. The cached QLP FITS and SHA256 values used here are enumerated in lead-numeric.json.', '']
 if EG[sid]['events']:
  evs=EG[sid]['events'];norm=[abs(e['nearest']['offset_in_gaia_sigma']) for e in evs]
  geometry=f'Gaia selection orbit: P={float(r["gaia_period_days"]):.6f} d, {r["nss_type"]}. Measured raw eclipse centers were compared against both edge-on Gaia conjunction kinds using the source-specific NSS covariance: nearest-conjunction absolute offsets span {min(norm):.2f}-{max(norm):.2f} propagated Gaia sigma across the selected events. Per-event measured times, predicted times, kinds, cycles and uncertainties are in lead-event-geometry.json. This conditional comparison alone cannot fix an unmeasured eclipse cycle count or source relationship.'
 else:
  geometry=f'Gaia selection orbit: P={float(r["gaia_period_days"]):.6f} d, {r["nss_type"]}. The nearest nominal conjunction to the retained screening window differs by {geo["closest"]["screen_minus_pred_phase"]:+.4f} Gaia cycles. This is a screening comparison, not an eclipse-derived period or source attribution.'
 lines[6]=geometry
