 if sid=='T100':lines+=['The P versus P/2 raw fold and source hashes are in lead-t100-harmonic.json and lead-t100-harmonic.png. The selected 0.679178-d timing fit in lead-timing.json is a photometric double-period representation, not an adopted orbital ephemeris.']
 report=B/tic/'REPORT.md';report.write_text('\n'.join(lines),encoding='utf-8')
